/** CLI-owned; regenerated by setu generate module or setu generate … --module <name>. */
import { type IRouterApi, type IServiceRegistry, requestService } from '@setu-ts/common';
import { productsService } from './products.service.ts';
import { PRODUCTS } from './products.token.ts';
import { registerProductsRoutes } from './products.controller.ts';

/** Registers the feature's request-bound service and its routes. */
export function registerProductsModule(router: IRouterApi, services?: IServiceRegistry): void {
  if (services === undefined) {
    throw new Error(
      'registerProductsModule needs the service registry: call registerModules(app.router, app.services).',
    );
  }
  services.register(PRODUCTS, requestService(productsService));
  registerProductsRoutes(router, services);
}
